'use strict';
state.coach={need:'habit',readiness:'unknown',prior:'',capacity:'',budget:'',evidence:''};state.showAll=false;
const coachProfile=()=>state.coach||(state.coach={need:'habit',readiness:'unknown',prior:'',capacity:'',budget:'',evidence:''});
document.body.classList.add('coach-app');
document.querySelector('.hero h1').innerHTML='この子の冬に、<br><em>ぴったりの学びを。</em>';
document.querySelector('.hero .intro').innerHTML='生徒の姿から、学ぶ理由と到達目標まで。<br>ご家庭と一緒に選べる冬のプランをつくります。';
document.querySelector('.hero .linkbutton').textContent='生徒のことを整理する ↓';
$('student').placeholder='例：佐鳴 はる';
const steps=document.createElement('div');steps.className='journey';steps.innerHTML='<button data-stage="1"><b>01</b> 生徒を知る</button><button data-stage="2"><b>02</b> 学びを選ぶ</button><button data-stage="3"><b>03</b> 提案を仕上げる</button>';document.querySelector('.top').after(steps);
const diagnosis=document.createElement('section');diagnosis.className='diagnosis';diagnosis.innerHTML=`<h3>もう一歩、生徒の姿を確かめる</h3><p class="muted">面談で確認した内容を入力。おすすめの理由と確認ポイントに反映します。</p><div class="diagnosis-grid"><label>いちばん近いつまずき<select id="need">${Object.entries(COACH.profiles).map(([k,v])=>`<option value="${k}" ${k==='habit'?'selected':''}>${v.name}</option>`).join('')}</select></label><label>基本問題の状態<select id="readiness"><option value="unknown">まだ確認していない</option><option value="support">説明やヒントが必要</option><option value="ready">類題を自力で解ける</option></select></label><label>冬に通える授業回数<input id="capacity" type="number" min="1" step="1" placeholder="例：24（未定なら空欄）"></label><label>ご予算の目安（税込・円）<input id="budget" type="number" min="0" step="1" placeholder="未定なら空欄"></label></div><label>今受けている授業・学習済みの単元<input id="prior" maxlength="250" placeholder="例：通常個別の数学／夏期に入試テーマⅠを受講"></label><label>答案や本人の言葉で確認したこと（社員用メモ）<textarea id="evidence" maxlength="1000" rows="2" placeholder="例：分数の通分で止まる。説明直後は解けるが、翌週に同じ誤り。"></textarea></label><div class="diagnosis-lead" id="diagnosis-lead"></div><button class="primary" id="show-candidates">この条件で講座を見比べる →</button></section>`;
document.querySelector('.subjectline').after(diagnosis);
const resultControls=document.createElement('div');resultControls.className='result-controls';resultControls.innerHTML='<label class="check"><input id="show-all" type="checkbox"> 比較のために、この学年の全プランも表示</label><button class="secondary" id="open-comparison">選んだ候補の内容を確認</button>';
document.querySelector('.resulthead').after(resultControls);
const interview=document.createElement('section');interview.className='interview';interview.id='interview';$('match-note').after(interview);
const tray=document.createElement('div');tray.className='selection-tray';tray.innerHTML='<div id="tray-summary"></div><button class="primary" id="to-proposal">提案書をつくる →</button>';document.body.append(tray);
const compare=document.createElement('section');compare.id='comparison';compare.className='comparison';compare.hidden=true;$('results').after(compare);
const review=document.createElement('section');review.id='plan-review';review.className='plan-review';document.querySelector('.proposal-layout').before(review);
const flowEditor=document.createElement('details');flowEditor.className='flow-editor';flowEditor.innerHTML='<summary>冬の進め方・ご家庭との約束を編集</summary><p class="muted">講座を選ぶと初期案を作ります。日程や本人の状況に合わせて調整してください。</p><label>はじめに<textarea id="phaseStart" rows="2" maxlength="500"></textarea></label><label>冬の学習中<textarea id="phaseDuring" rows="2" maxlength="500"></textarea></label><label>終わりに<textarea id="phaseEnd" rows="2" maxlength="500"></textarea></label><label>ご家庭にお願いしたいこと<textarea id="homeMessage" rows="2" maxlength="500"></textarea></label>';
document.querySelector('.editor').append(flowEditor);
const backup=document.createElement('div');backup.className='backup-actions';backup.innerHTML='<h3>別のPCでも編集を続ける</h3><button id="export-plan" class="secondary">編集用ファイルを保存</button><label class="filelabel">編集用ファイルを開く<input id="import-plan" type="file" accept=".json,application/json"></label><p class="muted">生徒名・社員用メモを含みます。保護者には上部の「提案書を保存」を使ってください。</p>';document.querySelector('.editor').append(backup);
const oldRenderFilters=renderFilters;renderFilters=function(){oldRenderFilters();const c=coachProfile();for(const k of ['need','readiness','capacity','budget','prior','evidence'])if($(k))$(k).value=c[k]??'';updateCoachLead();};
function updateCoachLead(){const p=coachProfile();$('diagnosis-lead').textContent=COACH.profiles[p.need]?.lead||COACH.profiles.habit.lead;}
const oldResults=renderResults;renderResults=function(){oldResults();const profile=coachProfile();document.querySelectorAll('#results .card').forEach(card=>{const id=card.querySelector('[data-add]').dataset.add,p=planById(id),info=COACH.explain({...p,composition:effective(p)},profile);card.querySelector('.reason').innerHTML='<b>'+esc(info.fit)+'</b>'+esc(info.reason);card.querySelector('.goal').innerHTML='<b>終了時に、ここを確認</b><br>'+esc(info.measure);const detail=card.querySelector('details');detail.insertAdjacentHTML('afterbegin','<div class="coach-check"><b>提案前に確かめること</b><ul>'+info.checks.map(x=>'<li>'+esc(x)+'</li>').join('')+'</ul></div>');const action=document.createElement('button');action.className='textbtn explain-button';action.textContent='面談での伝え方を見る';action.onclick=()=>showTalk(p);card.querySelector('.card-bottom').prepend(action);});
 const subject=state.subject==='すべて'?(state.grade.startsWith('小')?'算数':'数学'):state.subject;const info=COACH.subject[subject]||COACH.subject.数学;$('interview').innerHTML=`<div><span class="eyebrow">面談のひとこと</span><h3>${esc(subject)}の提案前に、ここを聞こう。</h3><p>${esc(info.question)}</p></div><div><b>見立ての確認</b><p>${esc(COACH.profiles[profile.need]?.lead||'')}</p></div>`;if(!document.querySelector('#results .card')&&!state.showAll)$('results').insertAdjacentHTML('beforeend','<button class="secondary" id="see-all-empty">この学年の全プランを見る</button>');$('see-all-empty')?.addEventListener('click',()=>{state.showAll=true;$('show-all').checked=true;renderResults()});updateTray();};
function showTalk(p){const i=COACH.explain({...p,composition:effective(p)},coachProfile()),copy=copyFor(p),d=document.createElement('dialog');d.className='talk-dialog';d.innerHTML=`<form method="dialog"><button class="textbtn close-dialog" value="close">閉じる ×</button></form><p class="eyebrow">社員向け・面談サポート</p><h2>${esc(p.grade+' '+p.subject+' '+p.kind)}</h2><div class="talk-block"><b>1　今の状況を伺う</b><p>${esc(i.question)}</p></div><div class="talk-block"><b>2　取り組む理由を伝える</b><p>「${esc(i.reason)}」</p></div><div class="talk-block"><b>3　学び方を具体的に</b><p>${esc(copy.desc)}</p><p>${esc(effective(p))}</p></div><div class="talk-block"><b>4　成果の確かめ方を共有</b><p>「${esc(i.measure)}」</p></div><details open><summary>こんな質問を受けたら</summary><p><b>全部受けた方がいいですか？</b><br>優先課題と通える回数から絞ります。すべての受講を前提にしません。</p><p><b>冬だけで点数は上がりますか？</b><br>点数を約束せず、まずはこの講座で扱う単元と確認方法を具体的に共有します。</p><p><b>自立学習は自習とどう違いますか？</b><br>計画・進捗確認・振り返りを通じて学習の進め方を身につけます。冬期の実際の対応は校舎の運用を確認します。</p></details><p class="muted">面談用の提案例。本人の答案と希望を踏まえて言い換えてください。</p>`;document.body.append(d);d.addEventListener('close',()=>d.remove(),{once:true});d.showModal();}
const originalAdd=addPlan;addPlan=async function(id){const p=planById(id),existing=state.selected.findIndex(x=>planById(x.id)?.subject===p.subject);if(existing>=0){if(!await ask('同じ教科の候補が選ばれています。今回の候補に入れ替えますか？'))return;state.selected.splice(existing,1)}originalAdd(id);const item=state.selected.find(x=>x.id===id),i=COACH.explain({...p,composition:effective(p)},coachProfile());Object.assign(item,{reason:i.reason,measure:i.measure,home:i.home,goal:copyFor(p).goal,focus:'',priority:'最優先'});updateTray();};
function reviewData(){const p=coachProfile();return COACH.load(state.selected,p.capacity,p.budget,state.extras)}
function updateTray(){const x=reviewData();$('tray-summary').innerHTML=`<b>${state.selected.length}講座を選択</b><span>${state.selected.length?`合計 ${x.total}回${x.unknown?' ＋ 回数未定':''}`:'まずは優先したい教科をひとつ。'}</span>${x.over?'<strong>通える回数を超えています</strong>':''}`;$('to-proposal').disabled=!state.selected.length;renderComparison();}
const oldCount=updateCount;updateCount=function(){oldCount();updateTray();};
function renderComparison(){$('comparison').innerHTML=`<h2>選んだ学びを、並べて確認</h2>${state.selected.length?'<div class="comparison-grid">'+state.selected.map((x,i)=>`<article><span class="eyebrow">候補 ${i+1}</span><h3>${esc(x.title)}</h3><p>${esc(x.composition)}</p><b>選んだ理由</b><p>${esc(x.reason)}</p><b>確かめること</b><p>${esc(x.measure||x.goal)}</p><button class="textbtn" data-tray-remove="${i}">この候補を外す</button></article>`).join('')+'</div>':'<p>候補がまだ選ばれていません。</p>'}<p class="muted">同じ教科の補強・強化は、重ねて受ける前提ではなく比較する候補です。選択時に入れ替えます。</p>`;}
function renderReview(){const x=reviewData(),p=coachProfile();const warnings=[];if(x.over)warnings.push(`通える${p.capacity}回に対して${x.total}回を選択しています。${x.total-Number(p.capacity)}回分、講座の優先順位を見直してください。`);if(x.unknown)warnings.push('オリジナルプランの授業形式・回数が未確定です。');if(x.overBudget)warnings.push(`ご予算を${money(x.amount-Number(p.budget))}超えています。`);if(!x.feesKnown)warnings.push('料金または教材費が未確認です。総額は確定していません。');if(!state.fields.school)warnings.push('提案書に載せる校舎名を入力してください。');$('plan-review').innerHTML=`<div><p class="eyebrow">無理なく取り組める冬へ</p><h2>${state.selected.length}講座 · ${x.total}回${x.unknown?' ＋ 未定分':''}</h2><p>${p.capacity?`通える回数の目安：${esc(p.capacity)}回`:'通える回数は未入力'}${x.remaining!==null&&!x.over&&!x.unknown?` ／ あと${x.remaining}回分の余裕`:''}</p></div><div>${warnings.length?'<ul>'+warnings.map(w=>'<li>'+esc(w)+'</li>').join('')+'</ul>':'<p>入力した回数・費用の範囲内です。実際の開講日時と本人の希望を確認してお渡しください。</p>'}</div>`;}
const oldProposal=renderProposal;renderProposal=function(){oldProposal();document.querySelectorAll('#selected-edit .selected-item').forEach((el,i)=>{const x=state.selected[i];el.insertAdjacentHTML('beforeend',`<details class="lesson-edit"><summary>重点単元・内容・成果の確認を詳しく編集</summary><label>優先順位<select data-edit="priority" data-index="${i}">${['最優先','次に取り組む','余裕があれば'].map(v=>`<option ${x.priority===v?'selected':''}>${v}</option>`).join('')}</select></label><label>重点単元・課題<input maxlength="250" data-edit="focus" data-index="${i}" value="${esc(x.focus||'')}" placeholder="面談で決めた単元を入力"></label><label>学習内容<textarea rows="3" maxlength="1000" data-edit="description" data-index="${i}">${esc(x.description)}</textarea></label><label>成果の確かめ方<textarea rows="2" maxlength="500" data-edit="measure" data-index="${i}">${esc(x.measure||x.goal)}</textarea></label><label>ご家庭での取り組み<textarea rows="2" maxlength="500" data-edit="home" data-index="${i}">${esc(x.home||'')}</textarea></label></details>`);});for(const k of ['phaseStart','phaseDuring','phaseEnd','homeMessage'])$(k).value=state.fields[k]||phaseDefaults()[k];renderReview();};
function phaseDefaults(){return {phaseStart:'答案や確認問題で現在の理解を確かめ、重点単元と目標を決めます。',phaseDuring:'選んだ講座で学習し、間違えた問題や覚え直す内容を記録。必要に応じて学習の進め方を調整します。',phaseEnd:'重点単元をもう一度確認し、できるようになったことと次の学習に続ける課題を共有します。',homeMessage:'取り組んだ量だけでなく、できるようになったことや工夫したことを聞いてみてください。'}};
const oldPaper=renderPaper;renderPaper=function(){oldPaper();document.querySelectorAll('#paper .paper-course').forEach((el,i)=>{const x=state.selected[i];if(x.priority)el.insertAdjacentHTML('afterbegin',`<p class="muted">${esc(x.priority)}</p>`);el.querySelector('.amount').insertAdjacentHTML('beforebegin',`${x.focus?'<p><b>重点単元・課題</b><br>'+esc(x.focus)+'</p>':''}${x.measure?'<p><b>成果の確かめ方</b><br>'+esc(x.measure)+'</p>':''}${x.home?'<p><b>ご家庭での取り組み</b><br>'+esc(x.home)+'</p>':''}`);});if(state.selected.length){const d=phaseDefaults();$('paper').querySelector('.paper-meta').insertAdjacentHTML('beforebegin',`<section class="winter-flow"><h2>冬の学びの進め方</h2>${[['phaseStart','はじめに'],['phaseDuring','学習中'],['phaseEnd','終わりに']].map(([k,t])=>`<p><b>${t}</b><br>${esc(state.fields[k]||d[k])}</p>`).join('')}<p><b>ご家庭へ</b><br>${esc(state.fields.homeMessage||d.homeMessage)}</p></section>`);}renderReview();updateTray();};
const originalReset=reset;reset=function(){state.coach={need:'habit',readiness:'unknown',prior:'',capacity:'',budget:'',evidence:''};originalReset();renderFilters();};
for(const k of ['need','readiness','prior','capacity','budget','evidence'])$(k).addEventListener('input',()=>{coachProfile()[k]=$(k).value;if(k==='need'){state.case=COACH.profiles[$('need').value].case;renderFilters()}updateCoachLead();renderResults()});
$('cases').addEventListener('click',e=>{const b=e.target.closest('[data-case]');if(!b)return;const p=coachProfile();if(COACH.profiles[p.need]?.case!==state.case)p.need={foundation:'habit',practice:'practice',ahead:'stretch',roots:'roots'}[state.case];renderFilters();renderResults();});
for(const k of ['phaseStart','phaseDuring','phaseEnd','homeMessage'])$(k).addEventListener('input',()=>{state.fields[k]=$(k).value;renderPaper()});
$('show-all').addEventListener('change',()=>{state.showAll=$('show-all').checked;renderResults()});
$('show-candidates').onclick=()=>{renderResults();document.querySelector('.resulthead').scrollIntoView({behavior:'smooth',block:'start'})};
$('to-proposal').onclick=()=>view('proposal');
$('open-comparison').onclick=()=>{$('comparison').hidden=false;renderComparison();$('comparison').scrollIntoView({behavior:'smooth'})};
$('comparison').addEventListener('click',e=>{const b=e.target.closest('[data-tray-remove]');if(b){state.selected.splice(Number(b.dataset.trayRemove),1);state.verified=false;updateCount();renderResults();}});
steps.addEventListener('click',e=>{const b=e.target.closest('[data-stage]');if(!b)return;const n=b.dataset.stage;view(n==='3'?'proposal':'discover');if(n==='1')$('finder').scrollIntoView({behavior:'smooth'});if(n==='2')document.querySelector('.resulthead').scrollIntoView({behavior:'smooth'});});
const originalView=view;view=function(v){originalView(v);tray.hidden=v!=='discover';steps.querySelectorAll('button').forEach(b=>b.classList.toggle('active',b.dataset.stage===(v==='proposal'?'3':'1')));};
function downloadJson(){const data={version:2,app:'sanaru-winter-guide',state};const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));a.download='冬期講座_編集用.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
$('export-plan').onclick=downloadJson;
$('import-plan').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>1000000)throw Error();const data=JSON.parse(await file.text());if(data.app!=='sanaru-winter-guide'||data.version!==2)throw Error();const checked=validatedPlanState(data.state);if(state.selected.length&&!await ask('現在の入力を、ファイルの提案内容に置き換えますか？'))return;applyPlanState(checked);toast('編集用ファイルを読み込みました')}catch{toast('このアプリで保存した編集用ファイルを選んでください。現在の入力は変更していません。')}finally{e.target.value='';}});
renderFilters();renderResults();updateCount();
